17	// `invoices` honours { id, amount, projectId, status } and `payments` honours
18	// { id, invoiceId, amount, date }. This change surfaces no audit records, so there is nothing to
19	// assert on the audit channel.
20	import { test, expect, type Page, type Locator } from '@playwright/test';
21	import { resetAndSeed } from '../support/seed';
