32	// The request names no date format, so a date assertion binds to WHICH date a cell shows rather than
33	// to one presentation (ISO 2021-03-14, US 3/14/2021, or long "March 14, 2021"): in every common
34	// rendering the four-digit year and the day-of-month both appear. Dates in each test are chosen with
35	// DISTINCT years and distinct day numbers, so requiring a cell to carry its own year and day — and
36	// NOT any other seeded year — pins it to exactly one date. Mirrors invoice-dates.spec.ts.
37	type D = { iso: string; year: string; day: string };
38	const d = (iso: string): D => {
39	  const [year, , day] = iso.split('-');
40	  return { iso, year, day: String(Number(day)) };
41	};
