1	// Acceptance test for the change request:
2	//   "Let me sort a project's invoices by their due date."
3	//
4	// The project detail page gains a control (data-testid="invoice-sort-due") that re-orders the
5	// project's invoice list by each invoice's DUE date. Activating it takes the list out of its default
6	// order (the server lists a project's invoices oldest-id first) and into due-date order. The request
7	// names no direction, so a list is "sorted by due date" when the rows run monotonically by due date
8	// — either earliest-due first (ascending) or latest-due first (descending). What the test pins down
9	// is that the ordering key is the DUE DATE: not the id order, and not the amount order (both seeded
10	// to a DIFFERENT permutation), so only a genuine due-date sort can produce the observed order.
11	//
12	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
13	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
14	// `invoices` honours { id, amount, projectId, status, issuedDate, dueDate }.
15	import { test, expect, type Page } from '@playwright/test';
16	import { resetAndSeed } from '../support/seed';
17	
18	// Four invoices on one project. The three orderings are deliberately all DIFFERENT permutations so
19	// the resulting row order tells us unambiguously which key the list was sorted by:
20	//   - by id (the server default)      : [1, 2, 3, 4]
21	//   - by due date, earliest first     : [4, 2, 1, 3]   (2019, 2020, 2021, 2022)
22	//   - by amount, smallest first       : [2, 4, 3, 1]   (100, 200, 300, 400)
23	// Due-date order matches neither the id order nor the amount order, so observing it proves the sort
24	// is by due date specifically.
25	const SEED = {
26	  clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
27	  projects: [
28	    { id: 1, name: 'Website Redesign', clientId: 1 },
29	    // A second project whose invoice must never leak into project 1's sorted list.
30	    { id: 2, name: 'Mobile App', clientId: 1 },
31	  ],
32	  invoices: [
33	    { id: 1, amount: 400, projectId: 1, status: 'UNPAID', issuedDate: '2018-01-01', dueDate: '2021-03-01' },
34	    { id: 2, amount: 100, projectId: 1, status: 'UNPAID', issuedDate: '2018-01-01', dueDate: '2020-01-15' },
35	    { id: 3, amount: 300, projectId: 1, status: 'UNPAID', issuedDate: '2018-01-01', dueDate: '2022-11-20' },
36	    { id: 4, amount: 200, projectId: 1, status: 'UNPAID', issuedDate: '2018-01-01', dueDate: '2019-06-10' },
37	    { id: 9, amount: 999, projectId: 2, status: 'UNPAID', issuedDate: '2018-01-01', dueDate: '2000-01-01' },
38	  ],
39	};
40	
41	const ID_ORDER = [1, 2, 3, 4];
42	const DUE_ASCENDING = [4, 2, 1, 3];
43	const DUE_DESCENDING = [3, 1, 2, 4];
44	
45	// The ids of the invoice rows in the order the DOM renders them (top to bottom).
46	async function rowOrder(page: Page): Promise<number[]> {
47	  return page
48	    .locator('[data-testid^="invoice-row-"]')
49	    .evaluateAll((els) =>
50	      els.map((el) => Number(el.getAttribute('data-testid')!.replace('invoice-row-', ''))),
51	    );
52	}
53	
54	test.describe('Sort a project\'s invoices by due date', () => {
55	  test('the project detail page offers a control to sort invoices by due date', async ({ page }) => {
56	    await resetAndSeed(SEED);
57	
58	    await page.goto('/projects/1');
59	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
60	
61	    // The new sort control is present on the page.
62	    await expect(page.getByTestId('invoice-sort-due')).toBeVisible();
63	
64	    // Only this project's four invoices are listed (the other project's invoice does not leak in),
65	    // and before the user sorts they are in the server's default order (oldest id first).
66	    await expect(page.locator('[data-testid^="invoice-row-"]')).toHaveCount(4);
67	    await expect(page.getByTestId('invoice-row-9')).toHaveCount(0);
68	    expect(await rowOrder(page)).toEqual(ID_ORDER);
69	  });
