71	  test('activating the control re-orders the invoices by their due date', async ({ page }) => {
72	    await resetAndSeed(SEED);
73	
74	    await page.goto('/projects/1');
75	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
76	    // Precondition: the list starts in its default (not due-date) order, so the reorder below is a
77	    // real effect of activating the control and not something that was already true.
78	    expect(await rowOrder(page)).toEqual(ID_ORDER);
79	
80	    await page.getByTestId('invoice-sort-due').click();
81	
82	    // The rows now run monotonically by due date. The request fixes no direction, so either
83	    // earliest-first or latest-first counts; what matters is that the order is keyed on the due date
84	    // (it is neither the id order nor the amount order).
