102	    const sorted = await rowOrder(page);
103	    expect([DUE_ASCENDING, DUE_DESCENDING]).toContainEqual(sorted);
104	
105	    // Reloading re-reads the page; the due-date sort the user asked for is still in effect and the
106	    // rows come back in the same order (the sort lives in the URL, not in throwaway component state).
107	    await page.reload();
108	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
109	    await expect(page.locator('[data-testid^="invoice-row-"]')).toHaveCount(4);
110	    expect(await rowOrder(page)).toEqual(sorted);
111	  });
112	});
